-- UNN MTH 101 (Elementary Mathematics I) CBT question bank
-- 174 questions mined from a "Solved Problem Sets" workbook (Chapter 1,
-- Sets 1-7 -- the clean MCQ + worked-solution portion of the source; Chapter 2
-- "Continuous Assessment Questions" and Chapter 3 "Practice Questions" are
-- free-response with no worked solutions and were left untouched).
--
-- Every answer was independently verified with sympy rather than trusted from
-- the workbook's own printed key; a small number of genuine discrepancies
-- were caught and corrected in the process. Permutation/combination word
-- problems, relations/functions/composition questions, and partial-fraction
-- questions were excluded as outside the official MTH 101 syllabus.
--
-- 3 exact-duplicate questions (the workbook repeats a few problems
-- across different Solved Problem Sets) were dropped during merge.

insert into public.cbt_questions
  (subject_id, subject_name, institution, faculty, department, level,
   question, options, correct_index, explanation, topic, is_general,
   semester, units)
values
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Express $\dfrac{1+i}{2-i}$ in the standard form $a+bi$.', '["$\\dfrac{1}{5}+\\dfrac{3}{5}i$", "$\\dfrac{1}{5}-\\dfrac{3}{5}i$", "$\\dfrac{3}{5}i-\\dfrac{1}{5}$", "$-\\dfrac{1}{5}-\\dfrac{3}{5}i$"]'::jsonb, 0, 'Multiply numerator and denominator by the conjugate $2+i$: $\dfrac{(1+i)(2+i)}{(2-i)(2+i)}=\dfrac{2+i+2i+i^2}{4+1}=\dfrac{1+3i}{5}=\dfrac{1}{5}+\dfrac{3}{5}i$.', 'Complex Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $z=\cos\theta+i\sin\theta$, express the real part of $z^3$ in terms of $\cos\theta$ only.', '["$4\\cos^3\\theta-3\\cos\\theta$", "$3\\cos\\theta-4\\cos^3\\theta$", "$-4\\cos^3\\theta-3\\cos\\theta$", "$4\\cos^3\\theta-\\cos\\theta$"]'::jsonb, 0, 'By De Moivre''s theorem $z^3=\cos3\theta+i\sin3\theta$, and the triple-angle identity gives $\cos3\theta=4\cos^3\theta-3\cos\theta$, which is the real part.', 'De Moivre''s Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $\alpha$ and $\beta$ are the roots of $x^2-3x+1=0$, find $\alpha^2+\beta^2$.', '["9", "8", "4", "7"]'::jsonb, 3, '$\alpha+\beta=3$ and $\alpha\beta=1$, so $\alpha^2+\beta^2=(\alpha+\beta)^2-2\alpha\beta=9-2=7$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Given that $\sin\theta=\dfrac{3}{5}$ with $\theta$ acute and $\sin\psi=\dfrac{4}{5}$ with $\psi$ obtuse, find $\cos(\theta-\psi)$.', '["2", "0", "1", "-1"]'::jsonb, 1, 'Since $\theta$ is acute, $\cos\theta=\dfrac{4}{5}$. Since $\psi$ is obtuse, its cosine is negative: $\cos\psi=-\dfrac{3}{5}$. Then $\cos(\theta-\psi)=\cos\theta\cos\psi+\sin\theta\sin\psi=\dfrac{4}{5}\left(-\dfrac{3}{5}\right)+\dfrac{3}{5}\cdot\dfrac{4}{5}=-\dfrac{12}{25}+\dfrac{12}{25}=0$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Solve for $x$: $2^{2x}-2^{x}-2=0$.', '["0", "-1", "1", "-2"]'::jsonb, 2, 'Let $y=2^x$. Then $y^2-y-2=0\Rightarrow(y-2)(y+1)=0$, so $y=2$ (rejecting $y=-1$ since $2^x>0$). Thus $2^x=2\Rightarrow x=1$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Evaluate $\cos75^\circ$.', '["$\\sqrt{2}(\\sqrt{3}+1)$", "$\\dfrac{1}{2\\sqrt2}(\\sqrt3-1)$", "$\\sqrt2(1-\\sqrt3)$", "$\\sqrt3(\\sqrt3-1)$"]'::jsonb, 1, '$\cos75^\circ=\cos(45^\circ+30^\circ)=\cos45^\circ\cos30^\circ-\sin45^\circ\sin30^\circ=\dfrac{\sqrt2}{2}\cdot\dfrac{\sqrt3}{2}-\dfrac{\sqrt2}{2}\cdot\dfrac12=\dfrac{\sqrt6-\sqrt2}{4}=\dfrac{1}{2\sqrt2}(\sqrt3-1)$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the principal argument of $\dfrac{2}{5i}$.', '["$-\\dfrac{\\pi}{2}$", "$\\dfrac{\\pi}{2}$", "$-\\dfrac{\\pi}{6}$", "$\\dfrac{\\pi}{6}$"]'::jsonb, 0, '$\dfrac{2}{5i}=\dfrac{2}{5i}\cdot\dfrac{-i}{-i}=-\dfrac{2i}{5}$, which lies on the negative imaginary axis, so its principal argument is $-\dfrac{\pi}{2}$.', 'Argand Diagram', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Express $-1+i\sqrt3$ in polar form.', '["$2\\left(\\cos\\dfrac{2\\pi}{3}+i\\sin\\dfrac{2\\pi}{3}\\right)$", "$2\\left(\\cos\\dfrac{2\\pi}{3}-i\\sin\\dfrac{2\\pi}{3}\\right)$", "$\\cos\\dfrac{2\\pi}{3}+i\\sin\\dfrac{2\\pi}{3}$", "$2\\left(-\\cos\\dfrac{2\\pi}{3}-i\\sin\\dfrac{2\\pi}{3}\\right)$"]'::jsonb, 0, 'The modulus is $\sqrt{(-1)^2+(\sqrt3)^2}=2$ and the argument is $\pi-\arctan(\sqrt3/1)=\dfrac{2\pi}{3}$ (second quadrant), giving $2\left(\cos\dfrac{2\pi}{3}+i\sin\dfrac{2\pi}{3}\right)$.', 'Argand Diagram', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Evaluate $(1-i)^4$.', '["4", "-4", "-2", "2"]'::jsonb, 1, '$(1-i)^2=1-2i+i^2=-2i$, so $(1-i)^4=(-2i)^2=4i^2=-4$.', 'Complex Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Convert $990^\circ$ to radians.', '["$-\\dfrac{11\\pi}{2}$", "$\\dfrac{11\\pi}{2}$", "$-\\dfrac{2\\pi}{11}$", "$\\dfrac{2\\pi}{11}$"]'::jsonb, 1, '$990^\circ=990\times\dfrac{\pi}{180}=\dfrac{11\pi}{2}$.', 'Circular Measure', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'One of the roots of $z^3+1=0$ is', '["$\\cos\\dfrac{5\\pi}{3}+i\\sin\\dfrac{5\\pi}{3}$", "$\\cos\\dfrac{5\\pi}{3}-i\\sin\\dfrac{5\\pi}{3}$", "$-\\cos\\dfrac{5\\pi}{3}-i\\sin\\dfrac{5\\pi}{3}$", "$\\sin\\dfrac{5\\pi}{3}+i\\cos\\dfrac{5\\pi}{3}$"]'::jsonb, 0, '$z^3=-1=\cos\pi+i\sin\pi$, so $z=\cos\dfrac{\pi+2k\pi}{3}+i\sin\dfrac{\pi+2k\pi}{3}$ for $k=0,1,2$, giving angles $\dfrac{\pi}{3},\pi,\dfrac{5\pi}{3}$. Taking $k=2$ gives the root $\cos\dfrac{5\pi}{3}+i\sin\dfrac{5\pi}{3}$.', 'Roots of Unity', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $A=\{a,b,c,g\}$ and $B=\{c,e,g\}$, find the symmetric difference $A\,\Delta\,B$.', '["$\\{a,b,e\\}$", "$\\{a,b\\}$", "$\\{a,e\\}$", "$\\{a,c,e\\}$"]'::jsonb, 0, '$A\,\Delta\,B=(A\setminus B)\cup(B\setminus A)=\{a,b\}\cup\{e\}=\{a,b,e\}$.', 'Set Theory', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Simplify $\dfrac{2}{\sqrt2+\sqrt{18}}$.', '["$\\dfrac{\\sqrt2}{4}$", "$-\\dfrac{\\sqrt2}{4}$", "$\\dfrac{\\sqrt2}{8}$", "$-\\dfrac{\\sqrt2}{8}$"]'::jsonb, 0, '$\sqrt{18}=3\sqrt2$, so the denominator is $4\sqrt2$. Thus $\dfrac{2}{4\sqrt2}=\dfrac{1}{2\sqrt2}=\dfrac{\sqrt2}{4}$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Simplify $3\sqrt2-2\sqrt8+\sqrt{32}$.', '["$-3\\sqrt2$", "$-2\\sqrt2$", "$248$", "$3\\sqrt2$"]'::jsonb, 3, '$\sqrt8=2\sqrt2$ and $\sqrt{32}=4\sqrt2$, so $3\sqrt2-2(2\sqrt2)+4\sqrt2=3\sqrt2-4\sqrt2+4\sqrt2=3\sqrt2$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the third term in the expansion of $(x+3y)^6$.', '["$135x^4y^3$", "$135x^{-2}y^3$", "$135x^4y^2$", "$x^2y^4$"]'::jsonb, 2, 'The third term corresponds to $r=2$: $\binom{6}{2}x^4(3y)^2=15\cdot x^4\cdot 9y^2=135x^4y^2$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'For which values of $x$ is the binomial expansion of $\left(1-\dfrac{1}{2x}\right)^{-3}$ valid?', '["$\\left(-\\infty,-\\dfrac12\\right]\\cup\\left[\\dfrac12,\\infty\\right)$", "$\\left(-\\infty,-\\dfrac12\\right)\\cup\\left(\\dfrac12,\\infty\\right)$", "$\\left(-\\dfrac12,\\dfrac12\\right)$", "$\\left[-\\dfrac12,\\dfrac12\\right]$"]'::jsonb, 1, 'The expansion converges when $\left|\dfrac{1}{2x}\right|<1$, i.e. $|2x|>1$, i.e. $x<-\dfrac12$ or $x>\dfrac12$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find all $x$ satisfying $|2x+1|>7$.', '["$x<3$ or $x>-4$", "$x>3$ or $x<-4$", "$-4<x<3$", "$x>3$ or $x>-4$"]'::jsonb, 1, '$2x+1>7\Rightarrow x>3$, or $2x+1<-7\Rightarrow x<-4$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\sum_{r=3}^{7}2^r$.', '["48", "-48", "248", "-248"]'::jsonb, 2, '$2^3+2^4+2^5+2^6+2^7=8+16+32+64+128=248$. (Alternatively, a geometric series with $a=8$, $r=2$, $n=5$: $S_5=\dfrac{8(2^5-1)}{2-1}=248$.)', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Express $0.7777\ldots$ (recurring) as a fraction.', '["$\\dfrac{7}{9}$", "$\\dfrac{17}{9}$", "$\\dfrac{9}{7}$", "$\\dfrac{3}{8}$"]'::jsonb, 0, 'Let $x=0.7777\ldots$, so $10x=7.7777\ldots$. Subtracting, $9x=7\Rightarrow x=\dfrac79$.', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the coefficient of $x^4$ in the binomial expansion of $(1-2x)^4$.', '["16", "8", "-16", "-8"]'::jsonb, 0, 'The term in $x^4$ is $\binom{4}{4}(1)^0(-2x)^4=16x^4$, so the coefficient is $16$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Solve the equation $\dbinom{16}{5+3x}=\dbinom{16}{1+2x}$.', '["3", "-3", "-2", "2"]'::jsonb, 3, 'By the symmetric property of combinations, $\binom{n}{r}=\binom{n}{n-r}$ means $r+(n-r)=n$. Applying $(5+3x)+(1+2x)=16$ gives $5x+6=16\Rightarrow x=2$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the 8th term in the expansion of $\left(\dfrac{1}{x^2}-x\right)^{11}$.', '["$462x^{-4}$", "$-330x^{-1}$", "$165x^2$", "$-330x^{-7}$"]'::jsonb, 1, 'The $(r+1)$th term is $\binom{11}{r}(x^{-2})^{11-r}(-x)^r$. For the 8th term, $r=7$: $\binom{11}{7}(-1)^7x^{-2(4)+7}=-330x^{-1}$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $\alpha$ and $\beta$ are the roots of $4x^2-16x+7=0$, find the equation whose roots are $\dfrac{\alpha}{\beta}$ and $\dfrac{\beta}{\alpha}$.', '["$7x^2-94x+7=0$", "$7x^2-61x+7=0$", "$7x^2-50x+7=0$", "$7x^2-34x+7=0$"]'::jsonb, 2, '$\alpha+\beta=4$, $\alpha\beta=\dfrac74$. The new sum is $\dfrac{\alpha^2+\beta^2}{\alpha\beta}=\dfrac{16-7/2}{7/4}=\dfrac{50}{7}$ and the new product is $1$. The equation $x^2-\dfrac{50}{7}x+1=0$ scales to $7x^2-50x+7=0$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Express $(4+6i)e^{i\pi/3}$ in standard form $a+bi$.', '["$(3-2\\sqrt3)+(3\\sqrt3+2)i$", "$(2-3\\sqrt3)+(2\\sqrt3+3)i$", "$(2-3\\sqrt3)+(2\\sqrt3+1)i$", "$(2-2\\sqrt3)+(3+2\\sqrt3)i$"]'::jsonb, 1, '$e^{i\pi/3}=\cos60^\circ+i\sin60^\circ=\dfrac12+\dfrac{\sqrt3}{2}i$. So $(4+6i)\left(\dfrac12+\dfrac{\sqrt3}{2}i\right)=2+2\sqrt3i+3i+3\sqrt3i^2=(2-3\sqrt3)+(2\sqrt3+3)i$.', 'Complex Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'The 5th and 13th terms of an arithmetic progression are $\dfrac12$ and $-\dfrac56$ respectively. Find the sum of the first 6 terms.', '["$\\dfrac{14}{3}$", "$\\dfrac{11}{3}$", "$\\dfrac{9}{2}$", "$\\dfrac{25}{6}$"]'::jsonb, 2, '$a+4d=\dfrac12$ and $a+12d=-\dfrac56$ give $d=-\dfrac16$, $a=\dfrac76$. Then $S_6=\dfrac62(2a+5d)=3\left(\dfrac{14}{6}-\dfrac56\right)=3\cdot\dfrac96=\dfrac92$.', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Given that $x\neq y$, which of the following sets is NOT empty?', '["$\\{(x,y)\\in\\mathbb{N}\\times\\mathbb{N}: x+y=11\\}$", "$\\{(x,y)\\in\\mathbb{Z}\\times\\mathbb{Z}: xy=1\\}$", "$\\{x\\in\\mathbb{R}: x^2+3=2\\}$", "$\\{x\\in\\mathbb{Z}: x^2+4=3\\}$"]'::jsonb, 0, 'Natural-number pairs with $x\neq y$ summing to 11 exist, e.g. $(5,6)$, so the first set is nonempty. In the second set $xy=1$ over the integers forces $x=y=1$ or $x=y=-1$, both excluded by $x\neq y$, so it is empty. The last two require $x^2=-1$, which has no real (hence no integer) solution.', 'Set Theory', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If the three consecutive terms of an arithmetic progression are $x$, $2x-1$ and $5x+1$, find $x$.', '["$\\dfrac23$", "$\\dfrac12$", "$-\\dfrac32$", "$3$"]'::jsonb, 2, 'Equal common differences give $(2x-1)-x=(5x+1)-(2x-1)$, i.e. $x-1=3x+2$, so $-2x=3\Rightarrow x=-\dfrac32$.', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'The $n$th partial sum of a sequence is $S_n=n^2+3n$. Find the $n$th term $X_n$.', '["$n^2+3n$", "$2n+3$", "$2n+1$", "$2(n+1)$"]'::jsonb, 3, '$X_n=S_n-S_{n-1}=(n^2+3n)-\left[(n-1)^2+3(n-1)\right]=(n^2+3n)-(n^2+n-2)=2n+2=2(n+1)$.', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'For what values of $n$ does the quadratic equation $m^2+nm+n=0$ have no real roots (in $m$)?', '["$(0,4)$", "$(-\\infty,0]\\cup[4,\\infty)$", "$(-\\infty,0)\\cup(4,\\infty)$", "$[0,4]$"]'::jsonb, 0, 'No real roots requires the discriminant to be negative: $n^2-4n<0\Rightarrow n(n-4)<0\Rightarrow 0<n<4$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find $\cos15^\circ-\cos75^\circ$.', '["$\\dfrac{\\sqrt3}{2}$", "$\\dfrac{1}{2}$", "$\\dfrac{\\sqrt3}{2}-\\dfrac12$", "$\\dfrac{\\sqrt2}{2}$"]'::jsonb, 3, '$\cos15^\circ-\cos75^\circ=\cos(45^\circ-30^\circ)-\cos(45^\circ+30^\circ)=2\sin45^\circ\sin30^\circ=2\cdot\dfrac{\sqrt2}{2}\cdot\dfrac12=\dfrac{\sqrt2}{2}$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If the roots of $x^2-px+8=0$ are $\alpha$ and $\alpha+2$, find the positive value of $p$.', '["36", "6", "8", "32"]'::jsonb, 1, 'Sum of roots: $2\alpha+2=p$. Product: $\alpha(\alpha+2)=8\Rightarrow\alpha^2+2\alpha-8=0\Rightarrow(\alpha+4)(\alpha-2)=0$, so $\alpha=2$ or $\alpha=-4$. Taking $\alpha=2$ gives $p=2(2)+2=6$ (positive).', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the principal argument of $3-3i$.', '["$\\dfrac{\\pi}{4}$", "$-\\dfrac{\\pi}{4}$", "$\\dfrac{7\\pi}{4}$", "$-\\dfrac{7\\pi}{4}$"]'::jsonb, 1, '$3-3i$ lies in the fourth quadrant with equal real and imaginary magnitudes, so its principal argument is $-\dfrac{\pi}{4}$.', 'Argand Diagram', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', '$A$ and $B$ are two nonempty sets with $A=B$. Which of the following is NOT necessarily true?', '["$A\\cap B\\neq\\emptyset$", "$A\\cup B\\neq\\emptyset$", "$A\\times B\\neq\\emptyset$", "$A\\,\\Delta\\,B\\neq\\emptyset$"]'::jsonb, 3, 'Since $A=B$, we have $A\setminus B=\emptyset$ and $B\setminus A=\emptyset$, so $A\,\Delta\,B=(A\setminus B)\cup(B\setminus A)=\emptyset$. Hence the statement $A\,\Delta\,B\neq\emptyset$ is false, while the other three all hold for nonempty equal sets.', 'Set Theory', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Convert $810^\circ$ to radians.', '["$\\dfrac{13\\pi}{2}$", "$\\dfrac{13\\pi}{12}$", "$\\dfrac{9\\pi}{2}$", "$\\dfrac{5\\pi}{3}$"]'::jsonb, 2, '$810^\circ=810\times\dfrac{\pi}{180}=\dfrac{9\pi}{2}$.', 'Circular Measure', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Express $0.424242\ldots$ (recurring) as a fraction in lowest terms.', '["$\\dfrac{42}{100}$", "$\\dfrac{14}{33}$", "$\\dfrac{27}{33}$", "$\\dfrac{21}{99}$"]'::jsonb, 1, 'Let $x=0.424242\ldots$. Then $100x=42.4242\ldots$, so $99x=42\Rightarrow x=\dfrac{42}{99}=\dfrac{14}{33}$.', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Express $-1-i$ in polar (exponential) form.', '["$e^{-i\\pi/4}$", "$e^{-i\\pi/4}\\sqrt2$", "$\\sqrt2\\,e^{3i\\pi/4}$", "$\\sqrt2\\,e^{5i\\pi/4}$"]'::jsonb, 3, '$|-1-i|=\sqrt2$ and its argument is $-\dfrac{3\pi}{4}$, which is coterminal with $\dfrac{5\pi}{4}$. So $-1-i=\sqrt2\,e^{5i\pi/4}$.', 'Argand Diagram', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'For what values of $x\in\mathbb{R}$ is the binomial expansion of $(5+x)^{-2}$ valid?', '["$-1<x<1$", "$|x|<5$", "$-3<x<3$", "$-6<x<6$"]'::jsonb, 1, 'Write $(5+x)^{-2}=5^{-2}\left(1+\dfrac{x}{5}\right)^{-2}$, valid when $\left|\dfrac{x}{5}\right|<1$, i.e. $|x|<5$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the term independent of $x$ in the expansion of $\left(x-\dfrac{1}{2x^2}\right)^6$.', '["$\\dfrac{15}{4}$", "$\\dfrac32$", "30", "$-\\dfrac{15}{4}$"]'::jsonb, 0, 'The general term is $\binom{6}{r}x^{6-r}\left(-\dfrac{1}{2x^2}\right)^r=\binom{6}{r}\left(-\dfrac12\right)^rx^{6-3r}$. This is independent of $x$ when $r=2$: $\binom{6}{2}\left(-\dfrac12\right)^2=15\cdot\dfrac14=\dfrac{15}{4}$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'An angle in the third quadrant has tangent $\dfrac35$. Find its cosine.', '["$-\\dfrac{5}{\\sqrt{34}}$", "$-\\dfrac{3}{\\sqrt{34}}$", "$\\dfrac{5}{\\sqrt{34}}$", "$\\dfrac{3}{\\sqrt{34}}$"]'::jsonb, 0, 'With opposite 3 and adjacent 5, the hypotenuse is $\sqrt{34}$. In the third quadrant both sine and cosine are negative, so $\cos\theta=-\dfrac{5}{\sqrt{34}}$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find $\tan75^\circ$.', '["$\\sqrt3+2$", "$\\sqrt3+\\sqrt2$", "$2-\\sqrt3$", "$\\sqrt3-2$"]'::jsonb, 0, '$\tan75^\circ=\tan(45^\circ+30^\circ)=\dfrac{1+\frac{1}{\sqrt3}}{1-\frac{1}{\sqrt3}}=\dfrac{\sqrt3+1}{\sqrt3-1}=\dfrac{(\sqrt3+1)^2}{2}=\dfrac{4+2\sqrt3}{2}=2+\sqrt3$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Solve for $x$: $\dbinom{20}{5+2x}=\dbinom{20}{x}$ (taking the non-trivial case).', '["3", "$\\dfrac32$", "5", "-5"]'::jsonb, 2, 'By the symmetric property, either $5+2x=x$ (giving $x=-5$, which makes $5+2x=-5<0$, invalid) or $(5+2x)+x=20\Rightarrow 3x=15\Rightarrow x=5$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $Z=\cos\theta+i\sin\theta$, find the imaginary part of $Z^2$.', '["$\\cos2\\theta$", "$\\sin2\\theta$", "$2\\sin\\theta$", "$2\\cos\\theta$"]'::jsonb, 1, 'By De Moivre''s theorem, $Z^2=\cos2\theta+i\sin2\theta$, so $\operatorname{Im}(Z^2)=\sin2\theta$ (equivalently $2\sin\theta\cos\theta$).', 'De Moivre''s Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $Z=x+iy$ satisfies $2Z+\bar Z=3-2i$, find $\bar Z$.', '["$2+2i$", "$1+2i$", "$1-2i$", "$-1+2i$"]'::jsonb, 1, '$2Z+\bar Z=2(x+iy)+(x-iy)=3x+iy=3-2i$, so $3x=3\Rightarrow x=1$ and $y=-2$. Thus $Z=1-2i$ and $\bar Z=1+2i$.', 'Complex Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the coefficient of $x^{-10}$ in the expansion of $\left(x-\dfrac{1}{2x^2}\right)^{11}$.', '["$\\dfrac{231}{32}$", "$-\\dfrac{165}{64}$", "$-\\dfrac{165}{4}$", "$\\dfrac{231}{16}$"]'::jsonb, 1, 'The general term is $\binom{11}{r}x^{11-r}\left(-\dfrac{1}{2x^2}\right)^r=\binom{11}{r}\left(-\dfrac12\right)^rx^{11-3r}$. Setting $11-3r=-10$ gives $r=7$, so the coefficient is $\binom{11}{7}\left(-\dfrac12\right)^7=330\left(-\dfrac{1}{128}\right)=-\dfrac{165}{64}$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'The 5th term of a geometric progression is 4 and the 9th term is 64. Find the first term and common ratio (taking the positive ratio).', '["$a=\\dfrac14,\\ r=4$", "$a=\\dfrac12,\\ r=2$", "$a=1,\\ r=2$", "$a=\\dfrac14,\\ r=2$"]'::jsonb, 3, '$ar^4=4$ and $ar^8=64$, so $r^4=16\Rightarrow r=2$ (taking the positive root). Then $a=\dfrac{4}{2^4}=\dfrac14$.', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'For what range of values of $k$ does $x^2+kx+k=0$ have distinct real roots?', '["$(-\\infty,0)\\cup(4,\\infty)$", "$(0,4)$", "$(0,\\infty)$", "$(-\\infty,0)$"]'::jsonb, 0, 'Distinct real roots require a positive discriminant: $k^2-4k>0\Rightarrow k(k-4)>0\Rightarrow k<0$ or $k>4$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'The first term of an arithmetic progression is 4 and the 7th term is 22. Find the sum of the first 20 terms.', '["560", "650", "680", "860"]'::jsonb, 1, '$a=4$, $a+6d=22\Rightarrow d=3$. Then $S_{20}=\dfrac{20}{2}(2(4)+19(3))=10(8+57)=650$.', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Solve $\dfrac{x^2-1}{x^2-3x+2}\le0$.', '["$[-1,1]$", "$[-1,1)\\cup(1,2)$", "$(-1,1)\\cup(1,2)$", "$[-1,2]$"]'::jsonb, 1, 'Factor: $\dfrac{(x-1)(x+1)}{(x-2)(x-1)}=\dfrac{x+1}{x-2}$ for $x\neq1$ (undefined there). Solving $\dfrac{x+1}{x-2}\le0$ gives $-1\le x<2$, and excluding $x=1$ gives $[-1,1)\cup(1,2)$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find all $x$ satisfying $|1-x|<5$.', '["$(-4,6)$", "$(-6,4)$", "$(-5,5)$", "$(4,-6)$"]'::jsonb, 0, '$-5<1-x<5\Rightarrow-6<-x<4\Rightarrow-4<x<6$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Evaluate $\cos165^\circ$.', '["$\\dfrac{\\sqrt6-\\sqrt2}{4}$", "$\\dfrac{\\sqrt6-\\sqrt2}{2}$", "$\\dfrac{3\\sqrt2-\\sqrt3}{2}$", "$-\\dfrac{\\sqrt2+\\sqrt6}{4}$"]'::jsonb, 3, '$\cos165^\circ=\cos(120^\circ+45^\circ)=\cos120^\circ\cos45^\circ-\sin120^\circ\sin45^\circ=-\dfrac12\cdot\dfrac{\sqrt2}{2}-\dfrac{\sqrt3}{2}\cdot\dfrac{\sqrt2}{2}=-\dfrac{\sqrt2+\sqrt6}{4}$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Simplify $i^{2525}$.', '["1", "$-i$", "$-1$", "$i$"]'::jsonb, 3, 'Since $i^4=1$, reduce the exponent mod 4: $2525=4(631)+1$, so $i^{2525}=i^1=i$.', 'Complex Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $A$ and $B$ are sets and $A-B=\emptyset$, which of the following must be true?', '["$A=B$", "$A\\subseteq B$", "$A\\cap B=\\emptyset$", "$A\\supset B$"]'::jsonb, 1, '$A-B=\emptyset$ means no element of $A$ fails to be in $B$, i.e. every element of $A$ is in $B$, so $A\subseteq B$.', 'Set Theory', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $\alpha+\beta=3$ and $\alpha\beta=5$, find $\alpha^5+\beta^5$.', '["57", "-57", "-49", "18"]'::jsonb, 1, 'Using power sums with $p_1=3$, $p_2=p_1^2-2(5)=-1$, $p_3=p_1p_2-5p_1=-18$, $p_4=p_1p_3-5p_2=-49$, $p_5=p_1p_4-5p_3=3(-49)-5(-18)=-147+90=-57$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'For what range of values of $x$ is $3x^2-x+2$ greater than $x^2+4x+5$?', '["$(-\\infty,-1)\\cup(3,\\infty)$", "$(-\\infty,-\\tfrac12)\\cup(3,\\infty)$", "$(-\\infty,1)\\cup(3,\\infty)$", "$(-1,\\infty)$"]'::jsonb, 1, '$3x^2-x+2>x^2+4x+5\Rightarrow2x^2-5x-3>0\Rightarrow(2x+1)(x-3)>0\Rightarrow x<-\tfrac12$ or $x>3$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $z=\cos\theta+i\sin\theta$, find $z+\dfrac1z$.', '["$2\\sin\\theta$", "$2\\cos\\theta$", "$2i\\sin\\theta$", "$2i\\cos\\theta$"]'::jsonb, 1, 'Since $|z|=1$, $\dfrac1z=\bar z=\cos\theta-i\sin\theta$, so $z+\dfrac1z=2\cos\theta$.', 'De Moivre''s Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Evaluate $\cos1300^\circ$.', '["$\\cos50^\\circ$", "$-\\cos50^\\circ$", "$-\\cos40^\\circ$", "$\\cos40^\\circ$"]'::jsonb, 2, '$1300^\circ=220^\circ+3(360^\circ)$, so $\cos1300^\circ=\cos220^\circ=-\cos(220^\circ-180^\circ)=-\cos40^\circ$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the coefficient of $x^{-7}$ in the expansion of $\left(x^2+\dfrac{1}{x^3}\right)^4$.', '["4", "6", "8", "12"]'::jsonb, 0, 'The general term is $\binom{4}{r}(x^2)^{4-r}(x^{-3})^r=\binom4r x^{8-5r}$. Setting $8-5r=-7$ gives $r=3$, so the coefficient is $\binom43=4$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Express $0.1242424\ldots$ (with 24 recurring) as a fraction in lowest terms.', '["$\\dfrac{42}{9900}$", "$\\dfrac{41}{330}$", "$\\dfrac{123}{9900}$", "$\\dfrac{41}{990}$"]'::jsonb, 1, 'Let $x=0.1242424\ldots$. Then $100x=12.42424\ldots$ and $10000x=1242.42424\ldots$, so $9900x=1230\Rightarrow x=\dfrac{1230}{9900}=\dfrac{41}{330}$.', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the principal argument of $-1-i$.', '["$\\dfrac{\\pi}{4}$", "$-\\dfrac{\\pi}{4}$", "$\\dfrac{3\\pi}{4}$", "$-\\dfrac{3\\pi}{4}$"]'::jsonb, 3, '$-1-i$ lies in the third quadrant with reference angle $\dfrac{\pi}{4}$, so its principal argument (in $(-\pi,\pi]$) is $-\pi+\dfrac{\pi}{4}=-\dfrac{3\pi}{4}$.', 'Argand Diagram', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Express $-1-i\sqrt3$ in polar form.', '["$2\\left(\\cos\\dfrac{2\\pi}{3}+i\\sin\\dfrac{2\\pi}{3}\\right)$", "$2\\left(\\cos\\dfrac{2\\pi}{3}-i\\sin\\dfrac{2\\pi}{3}\\right)$", "$2\\left(\\cos\\dfrac{\\pi}{3}-i\\sin\\dfrac{\\pi}{3}\\right)$", "$\\cos\\dfrac{2\\pi}{3}-i\\sin\\dfrac{2\\pi}{3}$"]'::jsonb, 1, '$|-1-i\sqrt3|=\sqrt{1+3}=2$. This point lies in the third quadrant with reference angle $\dfrac{\pi}{3}$, so its principal argument is $-\dfrac{2\pi}{3}$. Hence $-1-i\sqrt3=2\left(\cos\left(-\dfrac{2\pi}{3}\right)+i\sin\left(-\dfrac{2\pi}{3}\right)\right)=2\left(\cos\dfrac{2\pi}{3}-i\sin\dfrac{2\pi}{3}\right)$.', 'Argand Diagram', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'For a complex number $z$, $z\bar z$ is equal to', '["$2\\operatorname{Re}(z)$", "$2\\operatorname{Im}(z)$", "$|z|^2$", "$z^2$"]'::jsonb, 2, 'Let $z=x+iy$. Then $\bar z=x-iy$ and $z\bar z=(x+iy)(x-iy)=x^2+y^2=|z|^2$.', 'Complex Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $\alpha$ and $\beta$ are the roots of $x^2+px+q=0$ (with $q\neq0$), the roots of $qx^2+(2q-p^2)x+q=0$ are', '["$\\alpha+\\beta$ and $\\alpha-\\beta$", "$\\dfrac{\\alpha}{\\beta}-\\dfrac{\\beta}{\\alpha}$ and $1$", "$\\dfrac{\\alpha}{\\beta}$ and $\\dfrac{\\beta}{\\alpha}$", "$\\alpha\\beta$ and $1$"]'::jsonb, 2, '$\alpha+\beta=-p$, $\alpha\beta=q$. For $\dfrac{\alpha}{\beta}+\dfrac{\beta}{\alpha}=\dfrac{\alpha^2+\beta^2}{\alpha\beta}=\dfrac{p^2-2q}{q}$, matching the sum $-\dfrac{2q-p^2}{q}=\dfrac{p^2-2q}{q}$ of the new equation (divided by $q$), and $\dfrac{\alpha}{\beta}\cdot\dfrac{\beta}{\alpha}=1$ matches its product $\dfrac{q}{q}=1$. So the roots are $\dfrac{\alpha}{\beta}$ and $\dfrac{\beta}{\alpha}$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Solve $3x^2-17x+10<0$.', '["$x<\\dfrac23$", "$\\dfrac23<x<5$", "$x>5$", "$x<\\dfrac23 \\text{ or } x>5$"]'::jsonb, 1, 'The roots of $3x^2-17x+10=0$ are $x=\dfrac23$ and $x=5$ (factoring as $(3x-2)(x-5)$). Since the parabola opens upward, the expression is negative between the roots: $\dfrac23<x<5$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the term independent of $x$ in the expansion of $\left(\dfrac{2x}{3}+\dfrac{3}{2x}\right)^6$.', '["20", "15", "6", "1"]'::jsonb, 0, 'The general term is $\binom6r\left(\dfrac{2x}{3}\right)^{6-r}\left(\dfrac{3}{2x}\right)^r=\binom6r\left(\dfrac23\right)^{6-2r}x^{6-2r}$. This is independent of $x$ when $r=3$: $\binom63\left(\dfrac23\right)^3\left(\dfrac32\right)^3=20\cdot1=20$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', '$\cos70^\circ+\cos30^\circ$ is equal to', '["$\\sqrt2\\cos25^\\circ$", "$2\\sin50^\\circ\\sin20^\\circ$", "$\\cos90^\\circ$", "$2\\cos50^\\circ\\cos20^\\circ$"]'::jsonb, 3, 'By the sum-to-product formula, $\cos A+\cos B=2\cos\left(\dfrac{A+B}2\right)\cos\left(\dfrac{A-B}2\right)$. With $A=70^\circ,B=30^\circ$: $2\cos50^\circ\cos20^\circ$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Convert $630^\circ$ to radians.', '["$\\dfrac{7\\pi}{3}$", "$\\dfrac{7\\pi}{2}$", "$\\dfrac{\\pi}{2}$", "$\\dfrac{9\\pi}{2}$"]'::jsonb, 1, '$630^\circ=630\times\dfrac{\pi}{180}=\dfrac{7\pi}{2}$.', 'Circular Measure', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'An acute angle has sine $0.8$. Find its tangent.', '["$\\dfrac34$", "$-\\dfrac34$", "$\\dfrac43$", "$-\\dfrac43$"]'::jsonb, 2, '$\sin\theta=0.8=\dfrac45$, so $\cos\theta=\dfrac35$ (acute, positive). Thus $\tan\theta=\dfrac{4/5}{3/5}=\dfrac43$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Simplify $\dfrac{3+4i}{6+3i}$.', '["$\\dfrac{2+i}{3}$", "$\\dfrac{1+2i}{3}$", "$2+i$", "$\\dfrac{2-i}{3}$"]'::jsonb, 0, 'Multiply by the conjugate: $\dfrac{(3+4i)(6-3i)}{(6+3i)(6-3i)}=\dfrac{18-9i+24i+12}{36+9}=\dfrac{30+15i}{45}=\dfrac{2+i}{3}$.', 'Complex Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Which of the following is NOT correct?', '["$6!/3!=120$", "$6!-3!=3!$", "$4!+3!=30$", "$2!\\times3!=12$"]'::jsonb, 1, '$6!/3!=720/6=120$ (true). $6!-3!=720-6=714$, which is not equal to $3!=6$, so this statement is false. $4!+3!=24+6=30$ (true). $2!\times3!=2\times6=12$ (true).', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Let $A=\{\{y\},0,\{x\}\}$. Which of the following is true?', '["$y\\in A$", "$y\\subset A$", "$\\{y\\}\\subset A$", "$\\{y\\}\\in A$"]'::jsonb, 3, '$A$''s elements are exactly $\{y\}$, $0$, and $\{x\}$. Since $\{y\}$ itself is listed as an element of $A$, we have $\{y\}\in A$ (not $y\in A$, and not $\{y\}\subset A$ in general).', 'Set Theory', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'A sequence satisfies $u_1=1$, $u_2=2$, and $u_n=u_{n-1}+u_{n-2}$ for $n>2$. Find $u_7$.', '["12", "13", "20", "21"]'::jsonb, 3, '$u_3=3,u_4=5,u_5=8,u_6=13,u_7=u_6+u_5=13+8=21$.', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Solve for $t$ (with $t>0$): $2^{2t+1}-9(2^t)+4=0$.', '["3", "1", "2", "4"]'::jsonb, 2, 'Let $y=2^t$. Then $2y^2-9y+4=0\Rightarrow(2y-1)(y-4)=0$, so $y=\dfrac12$ or $y=4$. Since $t>0$, we need $y=2^t>1$, so $y=4\Rightarrow2^t=4\Rightarrow t=2$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $\alpha$ and $\beta$ are the roots of $m^2+km+6=0$ and $\alpha^2+\beta^2=52$, find the possible value(s) of $k$.', '["$\\pm12$", "$\\pm8$", "$\\pm6$", "$\\pm4$"]'::jsonb, 1, '$\alpha+\beta=-k$ and $\alpha\beta=6$. Then $\alpha^2+\beta^2=k^2-12=52\Rightarrow k^2=64\Rightarrow k=\pm8$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the constant term in the expansion of $\left(x-\dfrac{2}{x^2}\right)^6$.', '["-20", "60", "10", "-80"]'::jsonb, 1, 'The general term is $\binom6r x^{6-r}\left(-\dfrac{2}{x^2}\right)^r=\binom6r(-2)^rx^{6-3r}$. This is constant when $r=2$: $\binom62(-2)^2=15\times4=60$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the coefficient of $x^2$ in the binomial expansion of $\sqrt{1+x}$.', '["$\\dfrac13$", "$-\\dfrac12$", "$-\\dfrac18$", "$\\dfrac18$"]'::jsonb, 2, 'Using $(1+x)^{1/2}=1+\tfrac12x+\dfrac{\tfrac12(\tfrac12-1)}{2!}x^2+\cdots$, the coefficient of $x^2$ is $\dfrac{\tfrac12\cdot(-\tfrac12)}{2}=-\dfrac18$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $\tan(x+y)=2$ and $\tan(x-y)=1$, find $\tan2y$.', '["$\\dfrac13$", "$\\dfrac12$", "1", "$\\dfrac14$"]'::jsonb, 0, '$2y=(x+y)-(x-y)$, so $\tan2y=\dfrac{\tan(x+y)-\tan(x-y)}{1+\tan(x+y)\tan(x-y)}=\dfrac{2-1}{1+2}=\dfrac13$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Evaluate $\sin^2(22.5^\circ)-\cos^2(22.5^\circ)$.', '["$-\\dfrac{1}{\\sqrt2}$", "$\\dfrac{1}{\\sqrt2}$", "$-\\dfrac12$", "$\\dfrac12$"]'::jsonb, 0, '$\sin^2\theta-\cos^2\theta=-\cos2\theta$. With $\theta=22.5^\circ$, this is $-\cos45^\circ=-\dfrac{1}{\sqrt2}$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Given that $\cos^2\theta+\sin^2\theta=1$, simplify $\dfrac{1+\cos\theta+i\sin\theta}{1+\cos\theta-i\sin\theta}$.', '["$\\cos\\theta+i\\sin\\theta$", "$\\cos\\theta-i\\sin\\theta$", "1", "$2\\cos\\theta$"]'::jsonb, 0, 'Writing $1+\cos\theta=2\cos^2(\theta/2)$ and $\sin\theta=2\sin(\theta/2)\cos(\theta/2)$, both numerator and denominator factor with $2\cos(\theta/2)$, leaving $\dfrac{\cos(\theta/2)+i\sin(\theta/2)}{\cos(\theta/2)-i\sin(\theta/2)}=\dfrac{e^{i\theta/2}}{e^{-i\theta/2}}=e^{i\theta}=\cos\theta+i\sin\theta$.', 'Complex Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the term independent of $x$ in the expansion of $\left(\dfrac{2x}{3}-\dfrac{3}{2x}\right)^6$.', '["-20", "20", "10", "-10"]'::jsonb, 0, 'The general term is $\binom6r\left(\dfrac{2x}{3}\right)^{6-r}\left(-\dfrac{3}{2x}\right)^r=\binom6r\left(\dfrac23\right)^{6-r}\left(-\dfrac32\right)^rx^{6-2r}$. This is independent of $x$ when $r=3$: $\binom63\left(\dfrac23\right)^3\left(-\dfrac32\right)^3=20\left(\dfrac{8}{27}\right)\left(-\dfrac{27}{8}\right)=-20$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Write down the first three terms in the binomial expansion of $(1-2y)^{-4}$.', '["$1+8y+40y^2$", "$1-8y+40y^2$", "$1+8y-40y^2$", "$1+4y+10y^2$"]'::jsonb, 0, '$(1-2y)^{-4}=1+(-4)(-2y)+\dfrac{(-4)(-5)}{2!}(-2y)^2+\cdots=1+8y+10(4y^2)+\cdots=1+8y+40y^2+\cdots$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Solve the equation $\dbinom{12}{1-3y}=\dbinom{12}{1-2y}$ (taking the non-trivial case).', '["2", "-2", "4", "-4"]'::jsonb, 1, 'By the symmetric property of combinations, $(1-3y)+(1-2y)=12\Rightarrow2-5y=12\Rightarrow y=-2$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Given a set $X=\{a,b,c,d\}$, find the number of subsets in the power set of $X$.', '["8", "24", "16", "6"]'::jsonb, 2, 'A set with $n$ elements has $2^n$ subsets. With $n=4$, this gives $2^4=16$.', 'Set Theory', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the $n$th term of the sequence $-\dfrac12,\dfrac14,-\dfrac18,\dfrac{1}{16},\ldots$', '["$2^n$", "$\\left(\\dfrac12\\right)^n$", "$-\\left(\\dfrac12\\right)^n$", "$\\left(-\\dfrac12\\right)^n$"]'::jsonb, 3, 'This is a geometric sequence with $a=-\dfrac12$ and common ratio $r=-\dfrac12$, so $T_n=ar^{n-1}=\left(-\dfrac12\right)\left(-\dfrac12\right)^{n-1}=\left(-\dfrac12\right)^n$.', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If the roots of $3x^2-5x+p=0$ are equal, find $p$.', '["$\\dfrac{12}{25}$", "$\\dfrac{1}{25}$", "$\\dfrac{25}{12}$", "$\\dfrac{25}{13}$"]'::jsonb, 2, 'Equal roots require discriminant zero: $(-5)^2-4(3)(p)=0\Rightarrow25-12p=0\Rightarrow p=\dfrac{25}{12}$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Which of the following is NOT equivalent to $\cos2\theta$?', '["$\\sin^2\\theta-\\cos^2\\theta$", "$1-2\\sin^2\\theta$", "$2\\cos^2\\theta-1$", "$\\cos^2\\theta-\\sin^2\\theta$"]'::jsonb, 0, '$\cos2\theta=\cos^2\theta-\sin^2\theta=1-2\sin^2\theta=2\cos^2\theta-1$. The expression $\sin^2\theta-\cos^2\theta$ equals $-\cos2\theta$, not $\cos2\theta$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Simplify $\dfrac{1+\tan15^\circ}{1-\tan15^\circ}$.', '["$\\dfrac{\\sqrt3}{2}$", "$\\sqrt3$", "$1-\\sqrt3$", "$\\sqrt3+1$"]'::jsonb, 1, '$\dfrac{1+\tan15^\circ}{1-\tan15^\circ}=\dfrac{\tan45^\circ+\tan15^\circ}{1-\tan45^\circ\tan15^\circ}=\tan(45^\circ+15^\circ)=\tan60^\circ=\sqrt3$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Express $-\sqrt3+i$ in polar form.', '["$2\\left(\\cos30^\\circ+i\\sin30^\\circ\\right)$", "$2\\left(\\cos120^\\circ+i\\sin120^\\circ\\right)$", "$2\\left(\\cos150^\\circ+i\\sin150^\\circ\\right)$", "$2\\left(\\cos160^\\circ+i\\sin160^\\circ\\right)$"]'::jsonb, 2, '$|-\sqrt3+i|=\sqrt{3+1}=2$. This lies in the second quadrant with reference angle $30^\circ$, so the argument is $180^\circ-30^\circ=150^\circ$.', 'Argand Diagram', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the cardinality of the set $X=\{\emptyset\}$.', '["0", "2", "1", "3"]'::jsonb, 2, '$X$ contains exactly one element, namely the empty set $\emptyset$ itself, so $|X|=1$.', 'Set Theory', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the principal argument of $i^2$.', '["$\\dfrac{\\pi}{2}$", "$-\\dfrac{\\pi}{2}$", "$\\pi$", "$-\\pi$"]'::jsonb, 2, '$i^2=-1$, which lies on the negative real axis, so its principal argument is $\pi$.', 'Argand Diagram', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Express $\dfrac{1+i}{2-5i}$ in the form $a+bi$.', '["$\\dfrac{7+7i}{29}$", "$\\dfrac{-3+7i}{29}$", "$\\dfrac{-3-7i}{21}$", "$\\dfrac{3+7i}{21}$"]'::jsonb, 1, 'Multiply by the conjugate: $\dfrac{(1+i)(2+5i)}{(2-5i)(2+5i)}=\dfrac{2+5i+2i-5}{4+25}=\dfrac{-3+7i}{29}$.', 'Complex Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $z_1=3-i$ and $z_2=7+5i$, evaluate $2z_1-3z_2$.', '["$-15-17i$", "$15+17i$", "$-15+17i$", "$15-17i$"]'::jsonb, 0, '$2z_1-3z_2=2(3-i)-3(7+5i)=6-2i-21-15i=-15-17i$.', 'Complex Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $X$ and $Y$ are sets, then $(X-Y)''$ is equal to', '["$X''\\cup Y$", "$X''\\cap Y$", "$X\\cup Y''$", "$X''\\cap Y''$"]'::jsonb, 0, '$X-Y=X\cap Y''$, so by De Morgan''s law $(X-Y)''=(X\cap Y'')''=X''\cup(Y'')''=X''\cup Y$.', 'Set Theory', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Evaluate $\cos675^\circ$.', '["$\\dfrac{\\sqrt2}{2}$", "$-\\dfrac{\\sqrt2}{2}$", "$\\dfrac{\\sqrt3}{2}$", "$-\\dfrac{\\sqrt3}{2}$"]'::jsonb, 0, '$675^\circ=720^\circ-45^\circ$, so $\cos675^\circ=\cos(-45^\circ)=\cos45^\circ=\dfrac{\sqrt2}{2}$.', 'Circular Measure', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'An angle $\theta$ lies in the third quadrant and $\tan\theta=\dfrac{5}{3}$. Find $\cos\theta$.', '["$-\\dfrac{3\\sqrt{34}}{34}$", "$\\dfrac{3\\sqrt{34}}{34}$", "$-\\dfrac{5\\sqrt{34}}{34}$", "$\\dfrac{5\\sqrt{34}}{34}$"]'::jsonb, 0, 'With opposite $5$ and adjacent $3$, the hypotenuse is $\sqrt{5^2+3^2}=\sqrt{34}$. In the third quadrant cosine is negative, so $\cos\theta=-\dfrac{3}{\sqrt{34}}=-\dfrac{3\sqrt{34}}{34}$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Given the set $A=\{\{y\},0,\{x\}\}$, which of the following is true?', '["$y\\in A$", "$y\\subset A$", "$\\{y\\}\\subset A$", "$\\{y\\}\\in A$"]'::jsonb, 3, '$A$ has exactly three elements: $\{y\}$, $0$ and $\{x\}$. Since $\{y\}$ is itself listed as an element of $A$, $\{y\}\in A$ is true. Note $y$ (not $\{y\}$) is not an element of $A$, and $\{y\}\subset A$ would require $y\in A$, which fails.', 'Set Theory', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Evaluate $\cos15^\circ-\cos75^\circ$.', '["$\\dfrac{\\sqrt2}{2}$", "$\\dfrac{\\sqrt3}{2}$", "1", "$\\dfrac12$"]'::jsonb, 0, 'Using $\cos A-\cos B=-2\sin\left(\tfrac{A+B}{2}\right)\sin\left(\tfrac{A-B}{2}\right)$ with $A=15^\circ,B=75^\circ$: $-2\sin45^\circ\sin(-30^\circ)=2\cdot\tfrac{\sqrt2}{2}\cdot\tfrac12=\dfrac{\sqrt2}{2}$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $\alpha$ and $\beta$ are the roots of $y^2-py+2q=0$ and $\alpha^2+\beta^2=-6$, find the relation between $p$ and $q$.', '["$p=\\sqrt{4q-6}$", "$p=\\sqrt{4q+6}$", "$p^2=6-4q$", "$p=2\\sqrt{q-6}$"]'::jsonb, 0, '$\alpha+\beta=p$ and $\alpha\beta=2q$, so $\alpha^2+\beta^2=(\alpha+\beta)^2-2\alpha\beta=p^2-4q=-6\Rightarrow p^2=4q-6\Rightarrow p=\sqrt{4q-6}$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'A sequence is defined by $u(0)=1$ and $u(n)=\dfrac{u(n-1)}{n}$ for $n\geq1$. Find $u(4)$.', '["$\\dfrac{1}{24}$", "24", "$\\dfrac12$", "$\\dfrac{1}{4}$"]'::jsonb, 0, '$u(1)=\dfrac{u(0)}{1}=1$, $u(2)=\dfrac{u(1)}{2}=\dfrac12$, $u(3)=\dfrac{u(2)}{3}=\dfrac16$, $u(4)=\dfrac{u(3)}{4}=\dfrac{1}{24}$.', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Which of the following sets is an empty set?', '["$\\{x\\in\\mathbb{R}:1\\leq x\\leq1\\}$", "$\\{x\\in\\mathbb{R}:x^2\\geq0\\}$", "$\\{x\\in\\mathbb{N}:1\\leq x\\leq2\\}$", "$\\{x\\in\\mathbb{R}:x^2+4=0\\}$"]'::jsonb, 3, '$x^2+4=0\Rightarrow x^2=-4\Rightarrow x=\pm2i\notin\mathbb{R}$, so no real number satisfies this condition and the set is empty. The other sets each contain at least one element.', 'Set Theory', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the geometric mean between $2$ and $8$.', '["$\\pm4$", "$\\pm2$", "$\\pm8$", "$\\pm16$"]'::jsonb, 0, 'The geometric mean of $a$ and $b$ is $\pm\sqrt{ab}$. Here $\pm\sqrt{2\times8}=\pm\sqrt{16}=\pm4$.', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find all integers $n$ satisfying $1<|n|\leq4$.', '["$\\pm2,\\pm3,\\pm4$", "$\\pm1,\\pm2,\\pm3,\\pm4$", "$\\pm3,\\pm4$", "$\\pm2,\\pm4$"]'::jsonb, 0, '$1<|n|\leq4$ excludes $n=0,\pm1$ and allows $|n|=2,3,4$, giving $n=\pm2,\pm3,\pm4$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the polar form of $\sqrt3+i$.', '["$2(\\cos30^\\circ+i\\sin30^\\circ)$", "$2(\\cos60^\\circ+i\\sin60^\\circ)$", "$\\sqrt2(\\cos30^\\circ+i\\sin30^\\circ)$", "$2(\\cos(-30^\\circ)+i\\sin(-30^\\circ))$"]'::jsonb, 0, '$|\sqrt3+i|=\sqrt{3+1}=2$ and $\arg=\tan^{-1}\left(\dfrac{1}{\sqrt3}\right)=30^\circ$, so the polar form is $2(\cos30^\circ+i\sin30^\circ)$.', 'Argand Diagram', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Which of the following inclusions is false?', '["$\\mathbb{N}\\subset\\mathbb{Q}\\subset\\mathbb{R}$", "$\\mathbb{N}\\subset\\mathbb{Z}\\subset\\mathbb{Q}$", "$\\mathbb{Q}\\subset\\mathbb{Z}\\subset\\mathbb{N}$", "$\\mathbb{Z}\\subset\\mathbb{Q}\\subset\\mathbb{R}\\subset\\mathbb{C}$"]'::jsonb, 2, 'The correct chain of inclusions is $\mathbb{N}\subset\mathbb{Z}\subset\mathbb{Q}\subset\mathbb{R}\subset\mathbb{C}$. Option $\mathbb{Q}\subset\mathbb{Z}\subset\mathbb{N}$ reverses this and is false, since in fact $\mathbb{N}\subset\mathbb{Z}\subset\mathbb{Q}$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $\sec\theta=2$ and $0\leq\theta\leq\dfrac{\pi}{2}$, find $\sin\theta$.', '["$\\dfrac{\\sqrt3}{2}$", "$\\dfrac12$", "$\\dfrac34$", "$-\\dfrac12$"]'::jsonb, 0, '$\sec\theta=2\Rightarrow\cos\theta=\dfrac12$. Then $\sin\theta=\pm\sqrt{1-\cos^2\theta}=\pm\sqrt{1-\tfrac14}=\pm\dfrac{\sqrt3}{2}$. Since $\theta$ is in the first quadrant, $\sin\theta=\dfrac{\sqrt3}{2}$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Express $\sin15^\circ$ in surd form.', '["$\\dfrac{\\sqrt2}{4}(\\sqrt3-1)$", "$\\dfrac{\\sqrt2}{4}(\\sqrt3+1)$", "$-\\dfrac{\\sqrt2}{4}(\\sqrt3+1)$", "$\\dfrac{\\sqrt2}{4}(1-\\sqrt3)$"]'::jsonb, 0, '$\sin15^\circ=\sin(45^\circ-30^\circ)=\sin45^\circ\cos30^\circ-\cos45^\circ\sin30^\circ=\dfrac{\sqrt2}{2}\cdot\dfrac{\sqrt3}{2}-\dfrac{\sqrt2}{2}\cdot\dfrac12=\dfrac{\sqrt2}{4}(\sqrt3-1)$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Solve $|t+3|>2$.', '["$(-\\infty,-5)\\cup(-1,\\infty)$", "$(-5,-1)$", "$(-\\infty,-1)\\cup(5,\\infty)$", "$(1,5)$"]'::jsonb, 0, '$|t+3|>2\Rightarrow t+3>2$ or $t+3<-2\Rightarrow t>-1$ or $t<-5$, i.e. $t\in(-\infty,-5)\cup(-1,\infty)$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the value of $a$ (with $a>0$) if the coefficient of $x^3$ in the expansion of $(a+2x)^5$ is $320$.', '["2", "3", "1", "4"]'::jsonb, 0, 'The term in $x^3$ is $\binom53a^{2}(2x)^3=10a^2\cdot8x^3=80a^2x^3$. Setting $80a^2=320$ gives $a^2=4$, and since $a>0$, $a=2$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $\alpha$ and $\beta$ are the roots of $x^2+2x+1=0$, find $\alpha^3-\beta^3$.', '["0", "$2\\sqrt3$", "$\\sqrt2$", "1"]'::jsonb, 0, '$x^2+2x+1=(x+1)^2=0$ has the repeated root $x=-1$, so $\alpha=\beta=-1$, giving $\alpha^3-\beta^3=(-1)^3-(-1)^3=0$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the term independent of $x$ in the expansion of $\left(x+\dfrac{1}{2x}\right)^{12}$.', '["$\\dfrac{231}{16}$", "$\\dfrac{13}{6}$", "$\\dfrac{33}{16}$", "$-\\dfrac{33}{2}$"]'::jsonb, 0, 'The $(r+1)$th term is $\binom{12}{r}x^{12-r}\left(\dfrac{1}{2x}\right)^r=\binom{12}{r}2^{-r}x^{12-2r}$. This is constant when $r=6$: $\binom{12}{6}2^{-6}=924\times\dfrac{1}{64}=\dfrac{231}{16}$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'For what range of values of $k$ does the quadratic equation $4x^2+kx+1=0$ have complex roots?', '["$-4<k<4$", "$k<16$", "$k<-4$", "$k>4$"]'::jsonb, 0, 'Complex roots require discriminant $<0$: $k^2-4(4)(1)<0\Rightarrow k^2<16\Rightarrow-4<k<4$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $x=\sin\theta+\cos\theta$ and $y=\sin\theta+\cos(-\theta)$, then the relationship between $x$ and $y$ is', '["$x=y$", "$-x=y$", "$x^2=y^2$", "$x^2=y$"]'::jsonb, 0, 'Since cosine is an even function, $\cos(-\theta)=\cos\theta$, so $y=\sin\theta+\cos\theta=x$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the coefficient of $x$ in the expansion of $\left(x-\dfrac{1}{2x}\right)^{12}$.', '["0", "-33", "$\\dfrac{32}{3}$", "31"]'::jsonb, 0, 'The $(r+1)$th term is $\binom{12}{r}x^{12-r}\left(-\dfrac{1}{2x}\right)^r=\binom{12}{r}(-2)^{-r}x^{12-2r}$. A term in $x^1$ requires $12-2r=1$, i.e. $r=5.5$, which is not an integer. So the expansion has no term in $x$, and its coefficient is $0$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If the universal set is $\mu=\{a,b,c,d,e,f\}$, $A=\{a,b,d\}$ and $B=\{d,c\}$, find $(A-B)''$.', '["$\\{c,d,e,f\\}$", "$\\{b,c,d\\}$", "$\\{a,c,d,f\\}$", "$\\{d,c,f\\}$"]'::jsonb, 0, '$A-B=\{a,b,d\}-\{d,c\}=\{a,b\}$, so $(A-B)''=\mu-\{a,b\}=\{c,d,e,f\}$.', 'Set Theory', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the principal argument of $2+2i$.', '["$\\dfrac{\\pi}{4}$", "$\\dfrac{\\pi}{2}$", "$\\dfrac{3\\pi}{4}$", "$-\\dfrac{\\pi}{4}$"]'::jsonb, 0, '$\arg(2+2i)=\tan^{-1}\left(\dfrac{2}{2}\right)=\dfrac{\pi}{4}$, which already lies in $(-\pi,\pi]$.', 'Argand Diagram', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Given that $\cos A=\dfrac45$ and $\sin B=\dfrac{12}{13}$, with $A$ acute and $B$ obtuse, find $\tan(A+B)$.', '["$-\\dfrac{33}{56}$", "$\\dfrac{33}{56}$", "$-\\dfrac{63}{16}$", "$\\dfrac{63}{16}$"]'::jsonb, 0, '$\sin A=\dfrac35$ (acute), so $\tan A=\dfrac34$. Since $B$ is obtuse, $\cos B=-\dfrac{5}{13}$, so $\tan B=-\dfrac{12}{5}$. Then $\tan(A+B)=\dfrac{\tan A+\tan B}{1-\tan A\tan B}=\dfrac{\tfrac34-\tfrac{12}{5}}{1-\tfrac34\cdot\left(-\tfrac{12}{5}\right)}=-\dfrac{33}{56}$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Evaluate $\sin1300^\circ$.', '["$-\\sin40^\\circ$", "$\\sin40^\\circ$", "$\\cos40^\\circ$", "$-\\cos40^\\circ$"]'::jsonb, 0, '$1300^\circ=3(360^\circ)+220^\circ$, so $\sin1300^\circ=\sin220^\circ$. Since $220^\circ=180^\circ+40^\circ$, $\sin220^\circ=-\sin40^\circ$.', 'Circular Measure', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the polar form of $\dfrac{1}{3\sqrt2}(3i-3)$.', '["$\\cos\\dfrac{3\\pi}{4}+i\\sin\\dfrac{3\\pi}{4}$", "$\\cos\\dfrac{\\pi}{4}+i\\sin\\dfrac{\\pi}{4}$", "$2\\left(\\cos\\dfrac{3\\pi}{4}+i\\sin\\dfrac{3\\pi}{4}\\right)$", "$\\cos\\dfrac{\\pi}{4}-i\\sin\\dfrac{\\pi}{4}$"]'::jsonb, 0, '$z=\dfrac{1}{3\sqrt2}(3i-3)=\dfrac{1}{\sqrt2}(-1+i)=-\dfrac{1}{\sqrt2}+\dfrac{1}{\sqrt2}i$. Its modulus is $1$ and its argument is $\tfrac{3\pi}{4}$ (second quadrant), so $z=\cos\dfrac{3\pi}{4}+i\sin\dfrac{3\pi}{4}$.', 'Argand Diagram', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Evaluate $\sin37\tfrac12^\circ\sin7\tfrac12^\circ$.', '["$\\dfrac14(\\sqrt3-\\sqrt2)$", "$1-\\sqrt3$", "$\\sqrt3+7$", "$1+\\sqrt3$"]'::jsonb, 0, 'Using $\sin a\sin b=\tfrac12[\cos(a-b)-\cos(a+b)]$ with $a=37.5^\circ,b=7.5^\circ$: $\tfrac12[\cos30^\circ-\cos45^\circ]=\tfrac12\left(\dfrac{\sqrt3}{2}-\dfrac{\sqrt2}{2}\right)=\dfrac14(\sqrt3-\sqrt2)$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the equation whose roots are $-\dfrac{3}{\alpha}$ and $-\dfrac{3}{\beta}$, where $\alpha$ and $\beta$ are the roots of $2x^2-x+1=0$.', '["$x^2+3x+18=0$", "$x^2-3x-18=0$", "$x^2-3x+18=0$", "$2x^2+x-9=0$"]'::jsonb, 0, 'For $2x^2-x+1=0$: $\alpha+\beta=\tfrac12$, $\alpha\beta=\tfrac12$. New sum $=-3\left(\tfrac{1}{\alpha}+\tfrac{1}{\beta}\right)=-3\cdot\dfrac{\alpha+\beta}{\alpha\beta}=-3\cdot\dfrac{1/2}{1/2}=-3$. New product $=\dfrac{9}{\alpha\beta}=\dfrac{9}{1/2}=18$. The equation is $x^2-(\text{sum})x+\text{product}=x^2+3x+18=0$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Simplify $\dfrac{(2+i)(3-i)}{1+i}$.', '["$4-3i$", "$4+3i$", "$3i-4$", "$-4-3i$"]'::jsonb, 0, '$(2+i)(3-i)=6-2i+3i+1=7+i$. Then $\dfrac{7+i}{1+i}=\dfrac{(7+i)(1-i)}{2}=\dfrac{7-7i+i+1}{2}=\dfrac{8-6i}{2}=4-3i$.', 'Complex Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the range of values of $x$ which satisfies $x^2+x\leq6$.', '["$-3\\leq x\\leq2$", "$x\\geq2$", "$x\\leq3$", "$x\\leq2$"]'::jsonb, 0, '$x^2+x\leq6\Leftrightarrow(x+3)(x-2)\leq0$, which holds for $-3\leq x\leq2$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Evaluate $\dfrac13+\dfrac16+\dfrac{1}{12}+\cdots$', '["$\\dfrac23$", "$-\\dfrac23$", "$-\\dfrac13$", "$\\dfrac13$"]'::jsonb, 0, 'This is an infinite geometric series with first term $a=\tfrac13$ and common ratio $r=\tfrac12$. So $S_\infty=\dfrac{a}{1-r}=\dfrac{1/3}{1/2}=\dfrac23$.', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find three numbers in arithmetic progression whose sum is $21$ and whose product is $315$.', '["5, 7, 9", "0, 5, 21", "7, 2, 9", "2, 5, 7"]'::jsonb, 0, 'For $5,7,9$: the common difference is $9-7=7-5=2$ (an AP), their sum is $5+7+9=21$, and their product is $5\times7\times9=315$.', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'The sum of the first $n$ terms of a sequence is given by $S_n=n^2+3n$ for all values of $n$. Find the expression for the $r$th term, $U_r$.', '["$2(r+1)$", "$r^2+3r$", "$3r^2+1$", "$3(r-1)$"]'::jsonb, 0, '$U_r=S_r-S_{r-1}=(r^2+3r)-[(r-1)^2+3(r-1)]=2r+2=2(r+1)$.', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'A geometric progression has a common ratio of $2$. Find the value of $n$ for which the sum of $2n$ terms is $33$ times the sum of $n$ terms.', '["5", "2", "12", "33"]'::jsonb, 0, 'With $r=2$: $S_n=a(2^n-1)$ and $S_{2n}=a\left((2^n)^2-1\right)$. Requiring $S_{2n}=33S_n$ gives $(2^n)^2-1=33(2^n-1)$, i.e. $(2^n-1)(2^n+1)=33(2^n-1)$, so $2^n=32\Rightarrow n=5$.', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If the first term of an AP is $-5$ and the $8$th term is $58$, find the sum of the first $6$ terms.', '["105", "150", "501", "205"]'::jsonb, 0, '$a=-5$, and $T_8=a+7d=58\Rightarrow d=9$. Then $S_6=\dfrac62\left(2a+5d\right)=3\left(-10+45\right)=105$.', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Let $S$ be a set with $1\in S$, and suppose $k\in S$ implies $k+1\in S$ for every integer $k$. Which of the following must be true?', '["$S=\\mathbb{N}$", "$S\\subseteq\\mathbb{N}$ but $S\\neq\\mathbb{N}$", "$S\\cap\\mathbb{R}=\\{1\\}$", "$S\\cup\\mathbb{N}=\\mathbb{R}$"]'::jsonb, 0, '$\mathbb{N}$ is the smallest set containing $1$ that is closed under adding $1$ to any of its elements, which is exactly the defining property given for $S$. Hence $S=\mathbb{N}$.', 'Mathematical Induction', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'To prove by induction that $2^n>n$ for every integer $n$, the assumption $2^k>k$ should be used to establish which inequality?', '["$2\\times2^k>k+1$", "$2^{2k}>k+1$", "$2^{k^2}>(k+1)^2$", "$2^{k+1}>2(k+1)$"]'::jsonb, 0, 'Multiplying $2^k>k$ by $2$ gives $2^{k+1}=2\times2^k>2k\geq k+1$ (for $k\geq1$), so the required inequality is $2\times2^k>k+1$.', 'Mathematical Induction', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'The equation $2x^2-1=0$ has its solution in the set of', '["natural numbers", "integers", "real numbers", "rational numbers"]'::jsonb, 2, '$2x^2-1=0\Rightarrow x^2=\dfrac12\Rightarrow x=\pm\dfrac{1}{\sqrt2}$, which is irrational. So the solutions lie in $\mathbb{R}$ but not in $\mathbb{Q}$, $\mathbb{Z}$ or $\mathbb{N}$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $S$ and $T$ are sets, then $(S\cap T)\cup(S-T)$ is equal to', '["$S$", "$T$", "$S-T$", "$S\\cup T$"]'::jsonb, 0, '$(S\cap T)\cup(S-T)=(S\cap T)\cup(S\cap T'')=S\cap(T\cup T'')=S\cap\mu=S$.', 'Set Theory', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'In a certain examination involving $25$ students, $10$ passed Mathematics, $12$ passed Physics, while $5$ failed both subjects. The number of students that passed Mathematics only is', '["8", "10", "5", "12"]'::jsonb, 0, '$n(M\cup P)=25-5=20$, so $n(M\cap P)=n(M)+n(P)-n(M\cup P)=10+12-20=2$. Mathematics only $=n(M)-n(M\cap P)=10-2=8$.', 'Venn Diagrams', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Let $A$ be the set of all animals and $B$ the set of all cows. Then $A\cap B$ consists of', '["cows", "animals", "animals except cows", "cows and some animals"]'::jsonb, 0, 'Since every cow is an animal, $B\subset A$, so $A\cap B=B$, the set of cows.', 'Set Theory', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the $5$th term of the sequence $\{2n(n-1)\}_{n=1}^\infty$.', '["40", "20", "6", "$\\dfrac{25}{3}$"]'::jsonb, 0, '$T_n=2n(n-1)$, so $T_5=2(5)(4)=40$.', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If the $n$th term $U_n$ of a sequence is given by $U_n=5+3U_{n-1}$ and $U_4=35+U_3$, find $U_2$.', '["$\\dfrac{10}{3}$", "5", "25", "30"]'::jsonb, 0, 'From $U_4=35+U_3$ and $U_4=5+3U_3$: $5+3U_3=35+U_3\Rightarrow2U_3=30\Rightarrow U_3=15$. Then $U_3=5+3U_2\Rightarrow15=5+3U_2\Rightarrow U_2=\dfrac{10}{3}$.', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the sum of the series $4-\dfrac12+\dfrac14-\dfrac18+\dfrac{1}{16}-\cdots$', '["$\\dfrac{11}{3}$", "3", "5", "$-\\dfrac{11}{3}$"]'::jsonb, 0, 'Apart from the leading $4$, the remaining terms form a geometric series with $a=-\tfrac12$, $r=-\tfrac12$, summing to $\dfrac{-1/2}{1-(-1/2)}=-\dfrac13$. The total is $4-\dfrac13=\dfrac{11}{3}$.', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the coefficient of $x^{-4}$ in the expansion of $\left(x+\dfrac{1}{x^2}\right)^5$.', '["10", "6", "12", "20"]'::jsonb, 0, 'The $(r+1)$th term is $\binom5rx^{5-r}x^{-2r}=\binom5rx^{5-3r}$. This gives $x^{-4}$ when $5-3r=-4\Rightarrow r=3$, so the coefficient is $\binom53=10$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $\csc\theta=5$, find $\cos\theta$.', '["$\\pm\\dfrac{2\\sqrt6}{5}$", "$\\dfrac{25}{4}$", "$\\dfrac{5}{24}$", "$\\dfrac{\\sqrt6}{5}$"]'::jsonb, 0, '$\csc\theta=5\Rightarrow\sin\theta=\dfrac15$. Then $\cos\theta=\pm\sqrt{1-\sin^2\theta}=\pm\sqrt{1-\tfrac{1}{25}}=\pm\sqrt{\tfrac{24}{25}}=\pm\dfrac{2\sqrt6}{5}$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Given the complex number $5-3i$, find the modulus of its complex conjugate.', '["$\\sqrt{34}$", "34", "$\\sqrt{-34}$", "4"]'::jsonb, 0, 'The conjugate of $5-3i$ is $5+3i$, whose modulus is $\sqrt{5^2+3^2}=\sqrt{34}$ (equal to the modulus of the original number).', 'Complex Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Which of the following is a cube root of $i$?', '["$\\dfrac12(-\\sqrt3+i)$", "$i$", "$\\dfrac12(\\sqrt3-i)$", "$-1$"]'::jsonb, 0, '$i=\cos\tfrac{\pi}{2}+i\sin\tfrac{\pi}{2}$, so its cube roots are $\cos\tfrac{\pi/2+2k\pi}{3}+i\sin\tfrac{\pi/2+2k\pi}{3}$ for $k=0,1,2$. Taking $k=1$ gives $\cos\tfrac{5\pi}{6}+i\sin\tfrac{5\pi}{6}=-\dfrac{\sqrt3}{2}+\dfrac12i=\dfrac12(-\sqrt3+i)$.', 'Roots of Unity', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Simplify $(1+i)^{120}$.', '["$2^{60}$", "$2^{120}$", "$120\\sqrt2$", "1"]'::jsonb, 0, '$1+i=\sqrt2\,e^{i\pi/4}$, so $(1+i)^{120}=2^{60}e^{i30\pi}=2^{60}(\cos30\pi+i\sin30\pi)=2^{60}$.', 'De Moivre''s Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If the roots of a quadratic equation are $9$ and $\dfrac13$, find the equation.', '["$3x^2-28x+9=0$", "$x^2-28x+9=0$", "$x^2+28x-9=0$", "$3x^2+28x-9=0$"]'::jsonb, 0, 'Sum of roots $=9+\tfrac13=\tfrac{28}{3}$; product $=9\times\tfrac13=3$. The equation is $x^2-\tfrac{28}{3}x+3=0$, i.e. $3x^2-28x+9=0$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If one of the roots of the equation $2x^2-36x+b=0$ is twice the other, find the value of $b$.', '["144", "0", "72", "18"]'::jsonb, 0, 'Let the roots be $\alpha$ and $2\alpha$. Sum: $3\alpha=18\Rightarrow\alpha=6$, so the roots are $6$ and $12$. Product: $\alpha(2\alpha)=\dfrac{b}{2}\Rightarrow72=\dfrac{b}{2}\Rightarrow b=144$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $a$ and $b$ are the roots of the equation $x^2+x=2$, find the equation whose roots are $(1-a)$ and $(1-b)$.', '["$x(x-3)=0$", "$x(x-1)=0$", "$x^2-3x-2=0$", "$x^2-x-2=0$"]'::jsonb, 0, '$x^2+x-2=0\Rightarrow a=-2,b=1$. New roots: $1-a=3$, $1-b=0$. Sum $=3$, product $=0$, so the equation is $x^2-3x=0$, i.e. $x(x-3)=0$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $\alpha$ and $\beta$ are the roots of the equation $2x^2+5x-3=0$, find $\alpha^2+\beta^2$.', '["$\\dfrac{37}{4}$", "$\\dfrac{13}{4}$", "$-\\dfrac{13}{4}$", "$-\\dfrac{37}{4}$"]'::jsonb, 0, '$\alpha+\beta=-\dfrac52$, $\alpha\beta=-\dfrac32$. So $\alpha^2+\beta^2=(\alpha+\beta)^2-2\alpha\beta=\dfrac{25}{4}+3=\dfrac{37}{4}$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Simplify $\sin^4\theta-\cos^4\theta$.', '["$-\\cos2\\theta$", "$-\\sin2\\theta$", "$\\sin2\\theta-\\cos2\\theta$", "$\\cos^22\\theta$"]'::jsonb, 0, '$\sin^4\theta-\cos^4\theta=(\sin^2\theta+\cos^2\theta)(\sin^2\theta-\cos^2\theta)=\sin^2\theta-\cos^2\theta=-\cos2\theta$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $\sin\theta=\dfrac45$ and $\theta$ is acute, find $\cos2\theta$.', '["$-\\dfrac{7}{25}$", "$\\dfrac{7}{25}$", "$\\dfrac75$", "$-\\dfrac75$"]'::jsonb, 0, '$\sin\theta=\tfrac45\Rightarrow\cos\theta=\tfrac35$. Then $\cos2\theta=\cos^2\theta-\sin^2\theta=\tfrac{9}{25}-\tfrac{16}{25}=-\tfrac{7}{25}$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'One of the solutions of the equation $2\cos^2x-3\sin x=0$ in the interval $[0,2\pi]$ is', '["$\\dfrac{\\pi}{6}$", "$\\dfrac{\\pi}{3}$", "$-\\dfrac{\\pi}{3}$", "$-\\dfrac{\\pi}{6}$"]'::jsonb, 0, 'Using $\cos^2x=1-\sin^2x$: $2(1-\sin^2x)-3\sin x=0\Rightarrow2\sin^2x+3\sin x-2=0\Rightarrow(2\sin x-1)(\sin x+2)=0$. Since $\sin x=-2$ is impossible, $\sin x=\tfrac12\Rightarrow x=\tfrac{\pi}{6}$ or $\tfrac{5\pi}{6}$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the successor of the set $\{\emptyset\}$.', '["$\\{\\emptyset,\\{\\emptyset\\}\\}$", "$\\{\\emptyset,\\{\\emptyset,\\{\\emptyset\\}\\}\\}$", "$\\{\\{\\emptyset\\}\\}$", "$\\{\\emptyset\\}$"]'::jsonb, 0, 'The successor of a set $A$ is $S=A\cup\{A\}$. For $A=\{\emptyset\}$: $S=\{\emptyset\}\cup\{\{\emptyset\}\}=\{\emptyset,\{\emptyset\}\}$.', 'Set Theory', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Solve the inequality $-x^2-2x+3\geq0$.', '["$[-3,1]$", "$[-1,3]$", "$(-\\infty,-3]\\cup[1,\\infty)$", "$(-\\infty,-1]\\cup[3,\\infty)$"]'::jsonb, 0, '$-x^2-2x+3\geq0\Leftrightarrow x^2+2x-3\leq0\Leftrightarrow(x-1)(x+3)\leq0$, which holds for $-3\leq x\leq1$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'To prove by induction that $5^{2k}+3k-1$ is always a multiple of $9$, the assumption $5^{2k}+3k-1=9m$ should be used to show that $5^{2(k+1)}+3(k+1)-1$ equals', '["$9(25m-8k+3)$", "$9(25m-8k-3)$", "$9(25m+8k+3)$", "$9(25m+8k-3)$"]'::jsonb, 0, '$5^{2(k+1)}+3(k+1)-1=25\cdot5^{2k}+3k+2=25(5^{2k}+3k-1)-75k+25+3k+2=25(9m)-72k+27=9(25m-8k+3)$.', 'Mathematical Induction', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the number of elements in the power set of $\{\emptyset\}$.', '["2", "0", "1", "3"]'::jsonb, 0, '$\{\emptyset\}$ has exactly one element (namely $\emptyset$), so its power set has $2^1=2$ elements.', 'Set Theory', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the term independent of $t$ in the expansion of $\left(\dfrac32t^2+\dfrac{1}{3t}\right)^9$.', '["$\\dfrac{7}{18}$", "$\\dfrac{18}{7}$", "21", "$\\dfrac{22}{7}$"]'::jsonb, 0, 'The $(r+1)$th term is $\binom9r\left(\dfrac32\right)^{9-r}\left(\dfrac13\right)^rt^{18-3r}$. Independence of $t$ requires $r=6$, giving $\binom96\left(\dfrac32\right)^3\left(\dfrac13\right)^6=\dfrac{7}{18}$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the set of integers that satisfies $5>|n-2|\geq|n+1|$.', '["$\\{-2,-1,0\\}$", "$\\{0,1,2\\}$", "$\\{1,7,-3\\}$", "$\\{-1,-3,-4\\}$"]'::jsonb, 0, 'Checking integers directly: for $n=-2,-1,0$, $|n-2|$ is $4,3,2$ respectively (each less than $5$) and $|n+1|$ is $1,0,1$ respectively, and in each case $|n-2|\geq|n+1|$ holds. No other integer satisfies both conditions simultaneously.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Solve for $x$ if $\dbinom{16}{4-3x}=\dbinom{16}{-x}$.', '["-3", "4", "3", "-4"]'::jsonb, 0, 'By the symmetric property of combinations, $\binom{n}{r}=\binom{n}{n-r}$ requires $r+(n-r)=n$. Here $(4-3x)+(-x)=16\Rightarrow4-4x=16\Rightarrow x=-3$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Convert $555^\circ$ to radians.', '["$\\dfrac{37\\pi}{12}$", "$\\dfrac{121\\pi}{36}$", "$\\dfrac{9\\pi}{4}$", "$\\dfrac{11\\pi}{4}$"]'::jsonb, 0, '$555^\circ=555\times\dfrac{\pi}{180}=\dfrac{37\pi}{12}$ radians.', 'Circular Measure', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Simplify $\dfrac{2}{\sqrt{18}-\sqrt2}$.', '["$\\dfrac{\\sqrt2}{2}$", "$2\\sqrt2$", "$-\\dfrac{2\\sqrt2}{5}$", "$-\\dfrac{\\sqrt2}{2}$"]'::jsonb, 0, '$\sqrt{18}=3\sqrt2$, so $\dfrac{2}{\sqrt{18}-\sqrt2}=\dfrac{2}{3\sqrt2-\sqrt2}=\dfrac{2}{2\sqrt2}=\dfrac{1}{\sqrt2}=\dfrac{\sqrt2}{2}$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Solve for $x$ if $4^x+2^x-2=0$.', '["0", "-1", "1", "2"]'::jsonb, 0, 'Let $y=2^x$. Then $y^2+y-2=0\Rightarrow(y-1)(y+2)=0$, so $y=1$ or $y=-2$. Since $2^x>0$, discard $y=-2$. Then $2^x=1\Rightarrow x=0$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Express $\dfrac{3+2i}{4+i}$ in the form $a+bi$.', '["$\\dfrac{14}{17}+\\dfrac{5}{17}i$", "$\\dfrac{5}{17}+\\dfrac{14}{17}i$", "$\\dfrac{5}{17}-\\dfrac{14}{17}i$", "$\\dfrac{11}{17}-\\dfrac{10}{17}i$"]'::jsonb, 0, '$\dfrac{3+2i}{4+i}=\dfrac{(3+2i)(4-i)}{(4+i)(4-i)}=\dfrac{12-3i+8i+2}{17}=\dfrac{14+5i}{17}=\dfrac{14}{17}+\dfrac{5}{17}i$.', 'Complex Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the principal argument of $-1+i$.', '["$\\dfrac{3\\pi}{4}$", "$-\\dfrac{\\pi}{4}$", "$-\\dfrac{3\\pi}{4}$", "$\\dfrac{\\pi}{4}$"]'::jsonb, 0, '$-1+i$ lies in the second quadrant, with reference angle $\tan^{-1}(1)=\tfrac{\pi}{4}$, so its principal argument is $\pi-\tfrac{\pi}{4}=\tfrac{3\pi}{4}$.', 'Argand Diagram', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'One of the solutions to the equation $z^5=-1$ is', '["$e^{7\\pi i/5}$", "$-e^{i\\pi/3}$", "$e^{i\\pi/2}$", "$e^{3\\pi i/5}$"]'::jsonb, 0, 'Writing $-1=e^{i(\pi+2k\pi)}$, the fifth roots are $z=e^{i(\pi+2k\pi)/5}$ for $k=0,1,2,3,4$, i.e. arguments $\tfrac{\pi}{5},\tfrac{3\pi}{5},\pi,\tfrac{7\pi}{5},\tfrac{9\pi}{5}$. Taking $k=3$ gives $e^{7\pi i/5}$.', 'Roots of Unity', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', '$\cos5\theta\sin2\theta$ is equal to', '["$\\dfrac12[\\sin7\\theta-\\sin3\\theta]$", "$\\dfrac12[\\cos7\\theta+\\cos3\\theta]$", "$\\dfrac12[\\sin3\\theta+\\sin2\\theta]$", "$\\dfrac12[\\cos7\\theta+\\sin2\\theta]$"]'::jsonb, 0, 'Using $\sin7\theta=\sin(5\theta+2\theta)=\sin5\theta\cos2\theta+\cos5\theta\sin2\theta$ and $\sin3\theta=\sin(5\theta-2\theta)=\sin5\theta\cos2\theta-\cos5\theta\sin2\theta$, subtracting gives $\sin7\theta-\sin3\theta=2\cos5\theta\sin2\theta$, so $\cos5\theta\sin2\theta=\dfrac12[\sin7\theta-\sin3\theta]$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Given that $\cos A+\cos2A=0$, $\cos A$ is equal to', '["$-1,\\dfrac12$", "$1,\\dfrac12$", "$-\\dfrac12,1$", "$-1,-\\dfrac12$"]'::jsonb, 0, 'Using $\cos2A=2\cos^2A-1$: $\cos A+2\cos^2A-1=0\Rightarrow2\cos^2A+\cos A-1=0\Rightarrow(2\cos A-1)(\cos A+1)=0$, giving $\cos A=\dfrac12$ or $\cos A=-1$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the values of $k$ for which $x^2-kx+9=0$ has equal roots.', '["$\\pm6$", "$\\pm4$", "$k>4$", "$k<4$"]'::jsonb, 0, 'Equal roots require the discriminant to vanish: $k^2-4(1)(9)=0\Rightarrow k^2=36\Rightarrow k=\pm6$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Simplify $\dfrac{\ln27-\ln8}{\ln3-\ln27+\ln4}$ without using tables.', '["$-\\dfrac32$", "$\\dfrac32$", "$-\\dfrac23$", "$\\dfrac23$"]'::jsonb, 0, '$\ln27-\ln8=3\ln3-3\ln2$, and $\ln3-\ln27+\ln4=\ln3-3\ln3+2\ln2=-2\ln3+2\ln2$. So the ratio is $\dfrac{3(\ln3-\ln2)}{-2(\ln3-\ln2)}=-\dfrac32$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'For what values of $x$ is the binomial expansion of $(a+x)^\lambda$, with $a>0$, valid?', '["$|x|<a$", "$|x|>a$", "$x<a$", "$x>-a$"]'::jsonb, 0, 'Writing $(a+x)^\lambda=a^\lambda\left(1+\dfrac{x}{a}\right)^\lambda$, the expansion of $\left(1+\dfrac xa\right)^\lambda$ converges when $\left|\dfrac xa\right|<1$, i.e. $|x|<a$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'The number $e$ is', '["irrational", "complex", "an integer", "a natural number"]'::jsonb, 0, 'Euler''s number $e$ is irrational, i.e. $e\in\mathbb{Q}^c$; since $\mathbb{Q}^c\subseteq\mathbb{R}\subset\mathbb{C}$, it is real but not rational, complex-only, an integer, or natural.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $\alpha$ and $\beta$ are the roots of $x^2+4x-1=0$, find $(\alpha-\beta)^2$.', '["20", "$2\\sqrt5$", "$2\\sqrt3$", "12"]'::jsonb, 0, '$\alpha+\beta=-4$, $\alpha\beta=-1$. So $(\alpha-\beta)^2=(\alpha+\beta)^2-4\alpha\beta=16-4(-1)=20$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'In an examination involving $140$ students, $86$ passed Mathematics and $32$ passed Physics. If $40$ students failed both subjects, how many students passed both subjects?', '["18", "50", "86", "68"]'::jsonb, 0, '$n(M\cup P)=140-40=100$. Then $n(M\cap P)=n(M)+n(P)-n(M\cup P)=86+32-100=18$.', 'Venn Diagrams', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $\tan\theta=\dfrac34$ and $\dfrac{3\pi}{2}<\theta<2\pi$, find $\csc\theta$.', '["$-\\dfrac53$", "$\\dfrac53$", "$-\\dfrac45$", "$\\dfrac45$"]'::jsonb, 0, 'With $\tan\theta=\tfrac34$, $\csc^2\theta=1+\cot^2\theta=1+\tfrac{16}{9}=\tfrac{25}{9}$, so $\csc\theta=\pm\tfrac53$. In the fourth quadrant, $\sin\theta<0$, so $\csc\theta=-\tfrac53$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'For what values of $x$ does the series $\displaystyle\sum_{n=0}^{\infty}\dfrac{(1-x)^n}{(1+x)^{n+1}}$ converge?', '["$x>0$", "$-1<x<1$", "$x<0$", "$0<x<1$"]'::jsonb, 0, 'The series is geometric with ratio $r=\dfrac{1-x}{1+x}$, convergent when $|r|<1$, i.e. $|1-x|<|1+x|$. Squaring both sides: $x^2-2x+1<x^2+2x+1\Rightarrow4x>0\Rightarrow x>0$.', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Find the coefficient of $t^5$ in the expansion of $\left(2t-\dfrac3t\right)^{13}$.', '["$\\dbinom{13}{4}2^93^4$", "$\\dbinom{13}{3}2^{10}3^3$", "$\\dbinom{13}{3}2^93^4$", "$\\dbinom{13}{4}2^93^3$"]'::jsonb, 0, 'The $(r+1)$th term is $\binom{13}{r}(2t)^{13-r}\left(-\dfrac3t\right)^r=\binom{13}{r}2^{13-r}(-3)^rt^{13-2r}$. A term in $t^5$ requires $13-2r=5\Rightarrow r=4$, giving coefficient $\binom{13}{4}2^9(-3)^4=\binom{13}{4}2^93^4$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', '$0.213213213\ldots$ is equivalent to', '["$\\dfrac{71}{333}$", "$\\dfrac{71}{100}$", "$\\dfrac{213}{100}$", "$\\dfrac{213}{1000}$"]'::jsonb, 0, 'Let $x=0.213213213\ldots$. Then $1000x=213.213213\ldots$, so $1000x-x=213\Rightarrow999x=213\Rightarrow x=\dfrac{213}{999}=\dfrac{71}{333}$.', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'The sum of the first $n$ terms of a sequence is $S_n=n^2+4n$. Find the $n$th term of the sequence.', '["$2n+3$", "$2n+1$", "$2(n+1)$", "$2(n-1)$"]'::jsonb, 0, '$S_1=1+4=5=T_1$, and $S_2=4+8=12$, so $T_2=S_2-S_1=7$. Then $a=5$, $d=T_2-T_1=2$, giving $T_n=5+2(n-1)=2n+3$.', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Which of the following statements is NOT correct?', '["$\\mathbb{N}\\cup\\mathbb{Q}=\\mathbb{R}$", "$\\mathbb{Q}\\cap\\mathbb{Q}^c=\\emptyset$", "$\\mathbb{N}\\cap\\mathbb{Q}^c=\\emptyset$", "$\\mathbb{N}\\cup\\mathbb{Z}=\\mathbb{Z}$"]'::jsonb, 0, 'Since $\mathbb{Q}$ excludes irrational numbers, $\mathbb{N}\cup\mathbb{Q}=\mathbb{Q}\neq\mathbb{R}$, so this statement is false. The other three statements are all true.', 'Real Numbers', false, 'first', 3);
